import{_ as t,o as r,c as a,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Why the Course Looks Like This","description":"","frontmatter":{"source":"research/design-rationale.md"},"headers":[],"relativePath":"research/design-rationale.md","filePath":"research/design-rationale.md"}'),o={name:"research/design-rationale.md"};function n(i,e,d,h,l,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="why-the-course-looks-like-this" tabindex="-1">Why the Course Looks Like This <a class="header-anchor" href="#why-the-course-looks-like-this" aria-label="Permalink to &quot;Why the Course Looks Like This&quot;">​</a></h1><blockquote><p>This page explains the main design decisions in Building Apps with AI and the evidence behind each one. It&#39;s written for instructors adapting the course, for reviewers, and for students who want to know why they&#39;re being asked to do things this way. The evidence comes from the course&#39;s research review, completed in September 2026 (<a href="./landscape-report-2026-09.html">landscape report</a>), its October 2026 update (<a href="./landscape-update-2026-10.html">update report</a>), and the detailed <a href="./">research notes</a>. The <a href="#november-2026-update">November 2026 update</a> and <a href="#october-2026-update">October 2026 update</a> sections below map each change in those revisions to its reasons and evidence. Week numbers on this page are the current ones, in the 16-week semester. Until November 2026 the course ran in eight accelerated weeks; each old week N became weeks 2N−1 and 2N.</p></blockquote><p><strong>On this page:</strong> <a href="#the-short-version">The short version</a> · <a href="#how-strong-is-the-evidence">How strong is the evidence?</a> · <a href="#decisions-and-evidence">Decisions and evidence</a> · <a href="#november-2026-update">November 2026 update</a> · <a href="#october-2026-update">October 2026 update</a> · <a href="#what-we-deliberately-did-not-do">What we deliberately did not do</a> · <a href="#open-questions-and-how-this-course-measures-itself">Open questions and how this course measures itself</a> · <a href="#how-to-update-the-course">How to update the course</a> · <a href="#sources">Sources</a></p><hr><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><p><strong>Teach the loop, not the tool.</strong> University and industry courses on AI-assisted programming have converged on one shape: vibe-code and deploy something in week one, climb from chat to editor to agent, add specs, git, tests, review and security along the way, and grade students on explaining their code rather than on whether it runs (<a href="./landscape-report-2026-09.html">report</a>). The research supports that shape. AI help raises task completion, but without structure it weakens debugging and code comprehension, and struggling students come away believing they understand more than they do (<a href="https://dl.acm.org/doi/10.1145/3632620.3671116" target="_blank" rel="noreferrer">Prather et al.</a>; <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic</a>; <a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al.</a>). Vibe-coded apps fail in predictable places: public database keys without access rules, leaked secrets, invented package names and destructive agent commands (<a href="./landscape-report-2026-09.html#beginner-apps-break-where-browser-meets-server-not-in-the-syntax">report</a>). And the free tools change monthly.</p><p>So the course teaches one tool-agnostic workflow, <a href="./../resources/safe-loop.html">the Safe Loop</a>; gives every tool two tested fallbacks; saves everything to GitHub; checks understanding hardest in the agent weeks; builds its security unit around real breaches; and keeps every product detail in one dated file, <a href="./../TOOLS.html">Tool Handout</a>.</p><p><strong>October 2026 adds friction on purpose.</strong> New controlled studies agree that AI-assisted novices finish more and remember less, and that what helps is making students explain or repair code before it counts (<a href="./landscape-update-2026-10.html#four-new-studies-agree-ai-assisted-novices-finish-more-and-remember-less">update report</a>). So the Safe Loop gained two habits, <em>check first</em> and <em>teach back</em>; the safety contract gained a ninth rule; and the course became a 3-credit course with two studios a week, giving the extra practice room to happen (<a href="#october-2026-update">details</a>).</p><p><strong>November 2026 splits the course in two and spreads it over a semester.</strong> This course, Building Apps with AI, is now for students from any major who have taken one programming course, and it runs over a 16-week semester with two 75-minute studios a week. CS seniors and graduate students who have taken CS 3383 Software Engineering get a separate upper-division course, Engineering Software with AI. With a programming course behind every student, the course raises the hand-coding bar a little, and it schedules its checks around the University&#39;s final-examination rules (<a href="#november-2026-update">details</a>).</p><h2 id="how-strong-is-the-evidence" tabindex="-1">How strong is the evidence? <a class="header-anchor" href="#how-strong-is-the-evidence" aria-label="Permalink to &quot;How strong is the evidence?&quot;">​</a></h2><p>Not all of it is equally strong, and the course is designed with that in mind.</p><ul><li><strong>Randomized trials</strong> exist for a few questions: how AI help affects learning (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic, 2026</a>; <a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al.</a>, which studied high-school <em>math</em>, not coding; and a 2,379-student trial in which a course-integrated AI tutor lowered final grades, <a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers 26-1598</a>, whose abstract doesn&#39;t say what the tutor did or whether the course was in computing) and how it affects experienced developers&#39; speed (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR</a>).</li><li><strong>Small controlled studies</strong> from 2026 measure what happens after the task: recall two days later and claimed ownership (<a href="https://arxiv.org/abs/2609.21194" target="_blank" rel="noreferrer">Bergh et al.</a>, 55 students), and maintenance with the AI switched off (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>, 78 learners). Both are preprints.</li><li><strong>Observational studies and surveys</strong> describe what novices actually do when vibe coding (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>; <a href="https://arxiv.org/html/2605.24521v1" target="_blank" rel="noreferrer">Fawzy et al.</a>) and how courses are assessed (<a href="https://arxiv.org/abs/2608.05898" target="_blank" rel="noreferrer">Geng et al. syllabus study</a>; <a href="https://acm-education-genai-task-force.github.io/ACM_Taskforce_GenAI_Report_16Feb26.pdf" target="_blank" rel="noreferrer">ACM Task Force</a>).</li><li><strong>Course reports</strong> such as CMU 15-113&#39;s are rich but self-reported, and its instructor notes that an LLM drafted most of the report before he revised it (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). The Fall 2026 report was generated by an AI from about 630 anonymized answers with only light manual review; its quotes and statistics were checked by script, but its theme counts are an AI&#39;s reading (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>).</li><li><strong>Practitioner consensus</strong> (vendor guides and well-known engineers) supports the workflow itself. It is strong agreement, not controlled evidence.</li><li><strong>Security figures</strong> come mostly from vendors with a commercial interest (<a href="https://www.veracode.com/blog/spring-2026-genai-code-security/" target="_blank" rel="noreferrer">Veracode</a>; <a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">GitGuardian</a>; <a href="https://www.upguard.com/blog/everything-everywhere-systemic-data-exposure-in-supabase-apps" target="_blank" rel="noreferrer">UpGuard</a>; <a href="https://semgrep.dev/blog/2026/claude-opus-5-5-susvibes-benchmark" target="_blank" rel="noreferrer">Semgrep</a>), though they point the same way, and one academic audit agrees (<a href="https://arxiv.org/abs/2606.23130" target="_blank" rel="noreferrer">Deng et al.</a>).</li></ul><p>Where a decision rests on weaker evidence, the tables below say so.</p><hr><h2 id="decisions-and-evidence" tabindex="-1">Decisions and evidence <a class="header-anchor" href="#decisions-and-evidence" aria-label="Permalink to &quot;Decisions and evidence&quot;">​</a></h2><h3 id="sequence-and-pacing" tabindex="-1">Sequence and pacing <a class="header-anchor" href="#sequence-and-pacing" aria-label="Permalink to &quot;Sequence and pacing&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>Start with vibe coding in week 1</strong>, and deploy it in week 2</td><td>Across university and industry courses, students vibe-code and deploy a prototype in week one (<a href="./landscape-report-2026-09.html">report</a>). DeepLearning.AI&#39;s zero-experience course follows the same describe → generate → customize loop (<a href="https://www.deeplearning.ai/courses/build-with-andrew" target="_blank" rel="noreferrer">Build with Andrew</a>). The course teaches Karpathy&#39;s original meaning <em>and</em> why the field moved on (<a href="https://simonwillison.net/2025/Mar/19/vibe-coding/" target="_blank" rel="noreferrer">Willison</a>; <a href="https://karpathy.bearblog.dev/sequoia-ascent-2026/" target="_blank" rel="noreferrer">Karpathy, 2026</a>), because students will meet the term used both ways (<a href="https://itrevolution.com/product/vibe-coding-book/" target="_blank" rel="noreferrer">Kim &amp; Yegge</a>).</td><td><a href="./../weeks/01-hello-vibe-coding/">Week 1</a> · <a href="./../SYLLABUS.html#1-course-description">Syllabus §1</a></td></tr><tr><td><strong>A ladder of tools</strong>: chat with preview → app builders → editor assistant → own server → agent</td><td>CMU 15-113 put its first project on browser chatbots so students would feel that workflow&#39;s limits before meeting an editor assistant (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). Northeastern&#39;s CS 7180 climbs the same ladder explicitly (<a href="https://johnguerra.co/classes/aiCoding_spring_2026/" target="_blank" rel="noreferrer">NEU CS 7180</a>). Each rung comes after the habits it needs.</td><td><a href="./../SYLLABUS.html#the-ladder-of-tools">Syllabus §4</a></td></tr><tr><td><strong>Spec first, in week 5</strong>, with WHEN … THE APP SHALL … criteria</td><td>Vendor guides agree on spec or plan before code (<a href="https://github.blog/ai-and-ml/generative-ai/spec-driven-development-with-ai-get-started-with-a-new-open-source-toolkit/" target="_blank" rel="noreferrer">GitHub Spec Kit</a>; <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">Codex best practices</a>; <a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). EARS-style criteria are learnable by non-programmers (<a href="https://kiro.dev/docs/specs/feature-specs/" target="_blank" rel="noreferrer">Kiro</a>). CMU students rated writing the spec as <em>harder</em> than managing agents (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>), so it is practiced early, before agents; in Fall 2026 CMU itself moved spec-driven development from homework 8 to week 5 (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>). Writing skill predicts vibe-coding proficiency (<a href="https://arxiv.org/abs/2603.14133" target="_blank" rel="noreferrer">Thorgeirsson et al.</a>), and every spec now gets a Goldfish test (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">EGM</a>). <em>No study yet shows that spec-first helps novices learn</em> (<a href="./landscape-update-2026-10.html#professional-developers-trust-ai-only-where-they-can-verify-it">update report</a>).</td><td><a href="./../weeks/05-spec-first/">Week 5</a> · <a href="./../templates/SPEC.html">SPEC template</a> · <a href="./../resources/prompt-patterns.html#18-the-goldfish-test">Goldfish test</a></td></tr><tr><td><strong>Read, debug and own the code in weeks 7–8</strong>, with an AI-off Debug Clinic and &quot;You write it&quot;: the student writes a function from a short spec</td><td>Debugging is the skill AI use erodes most (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic</a>). CMU&#39;s highest understanding scores came on the assignment where students read and partly wrote the code (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). CS1-LLM&#39;s final exam was mostly AI-free tracing, explaining, testing and debugging, and results largely matched pre-AI cohorts (<a href="https://arxiv.org/pdf/2406.15379" target="_blank" rel="noreferrer">CS1-LLM</a>). Coding practice, not awareness, predicted who checked AI code (<a href="https://arxiv.org/html/2605.24521v1" target="_blank" rel="noreferrer">Fawzy et al.</a>). Since October 2026 students write a first automated test from a worked example (since November 2026 in week 4, before the project weeks), so that tests can be written <em>before</em> the code from then on: tests an AI writes after faulty code catch fewer faults (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>).</td><td><a href="./../weeks/07-read-and-debug/">Week 7</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic" target="_blank" rel="noreferrer">Debug Clinic</a> · <a href="./../weeks/08-own-it/">Week 8</a> · <a href="./../weeks/04-undo-compare-explain/">Week 4</a> · <a href="./../resources/safe-loop.html#check-first">check first</a></td></tr><tr><td><strong>Deploy early and often</strong>: GitHub Pages in week 2, dedicated weeks for secrets (week 9) and deployment (week 10)</td><td>CMU students reported that deployment took more time than coding (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). Deploying a small thing first makes the week 10 full-stack deploy a second attempt, not a first.</td><td><a href="./../weeks/02-ship-your-page/">Week 2</a> · <a href="./../weeks/09-apis-and-secrets/">Week 9</a> · <a href="./../weeks/10-servers-and-deployment/">Week 10</a></td></tr><tr><td><strong>Hold agents until week 11</strong></td><td>UChicago and Northeastern both reserve autonomous agents for the second half (<a href="https://mpcs-courses.cs.uchicago.edu/2025-26/spring/courses/mpcs-51238-1" target="_blank" rel="noreferrer">UChicago</a>; <a href="https://johnguerra.co/classes/aiCoding_spring_2026/" target="_blank" rel="noreferrer">NEU</a>). DORA finds AI amplifies existing practice, and names strong version control and small batches as conditions for it to help (<a href="https://services.google.com/fh/files/misc/2025_dora_ai_capabilities_model.pdf" target="_blank" rel="noreferrer">DORA</a>), so git, specs and tests come first. At CMU, understanding and code-reading scores fell once agents took over (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>).</td><td><a href="./../weeks/11-agents/">Week 11</a></td></tr><tr><td><strong>Open the agent week by &quot;being the agent&quot;</strong>: change an app using only an agent&#39;s tools</td><td>Utah had students change a calculator using only an agent&#39;s tools (<a href="https://github.com/utah-cs3960-sp26/calculator" target="_blank" rel="noreferrer">Utah calculator repo</a>). Stanford&#39;s Fall 2026 course opens by showing students how an agent works inside (<a href="https://themodernsoftware.dev/" target="_blank" rel="noreferrer">CS146S</a>). Both show the loop at no cost before students hand it control.</td><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent" target="_blank" rel="noreferrer">Be the Agent</a></td></tr><tr><td><strong>Data, security and review in weeks 13–14</strong>, built around an attack-your-own-database lab</td><td>The most instructive failures share one root cause: a public key plus missing authorization rules (<a href="https://www.superblocks.com/blog/lovable-vulnerabilities" target="_blank" rel="noreferrer">Superblocks on Lovable</a>; <a href="https://www.wiz.io/blog/exposed-moltbook-database-reveals-millions-of-api-keys" target="_blank" rel="noreferrer">Wiz on Moltbook</a>). In September 2026 the same root cause turned up in 16,326 Supabase databases, and tables that agents create through the API start without RLS (<a href="https://www.upguard.com/blog/everything-everywhere-systemic-data-exposure-in-supabase-apps" target="_blank" rel="noreferrer">UpGuard</a>). Newer models have not written more secure code (<a href="https://www.veracode.com/blog/spring-2026-genai-code-security/" target="_blank" rel="noreferrer">Veracode Spring 2026</a>); working code was also secure only 54.8% of the time in one 2026 benchmark (<a href="https://semgrep.dev/blog/2026/claude-opus-5-5-susvibes-benchmark" target="_blank" rel="noreferrer">Semgrep</a>), so waiting for better models is not a plan. The attack page is now hosted on the course site, so the lab needs no extra repository (review H7).</td><td><a href="./../weeks/13-data-and-access/">Week 13</a> · <a href="https://github.com/Boyu-Zhang-UOI/vc101-rls-lab" target="_blank" rel="noreferrer">RLS Attack Lab</a> · <a href="./../weeks/14-security-and-review/">Week 14</a> · <a href="./../resources/case-studies.html">case studies</a></td></tr><tr><td><strong>Four projects, from toy to real stakes</strong>: home page → game → a tool you&#39;d use → deployed capstone</td><td>The near-universal opening is a single-file page, then a game, which needs no backend and gives instant feedback (<a href="https://www.deeplearning.ai/courses/build-with-andrew" target="_blank" rel="noreferrer">DLAI</a>; <a href="https://codelabs.developers.google.com/vibe-code-with-gemini-in-aistudio" target="_blank" rel="noreferrer">Google codelab</a>). Vanderbilt builds on learners&#39; own tools and files (<a href="https://www.coursera.org/learn/build-anything-with-ai" target="_blank" rel="noreferrer">Coursera</a>). The capstone follows CMU 15-113&#39;s deployed app with live URL, README, prompt log and demo video (<a href="https://www.cs.cmu.edu/~113/" target="_blank" rel="noreferrer">CMU 15-113</a>).</td><td><a href="./../projects/">Projects</a></td></tr></tbody></table><h3 id="tools-and-cost" tabindex="-1">Tools and cost <a class="header-anchor" href="#tools-and-cost" aria-label="Permalink to &quot;Tools and cost&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>$0 required</strong></td><td>The free-tool landscape can support an eight-week course (<a href="./landscape-report-2026-09.html#free-tiers-still-exist-in-2026-but-they-are-capped-age-restricted-and-change-monthly">report</a>); over 16 weeks the same work is spread across more of the monthly allowance resets, though tools also have more time to change (re-checked before week 9; pre-cohort checklist). Michigan runs on free local models and CMU on free tools (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">UMich</a>; <a href="https://www.cs.cmu.edu/~113/" target="_blank" rel="noreferrer">CMU 15-113</a>). Where a university plan ran short, UChicago students had to buy a paid plan (<a href="https://mpcs-courses.cs.uchicago.edu/2025-26/spring/courses/mpcs-51238-1" target="_blank" rel="noreferrer">UChicago</a>), and MOOC learners object to subscription costs (<a href="https://www.coursera.org/learn/claude-code/reviews" target="_blank" rel="noreferrer">Coursera reviews</a>). In October 2026, the new non-major courses mostly assumed students pay ($25–$100 a month at Stanford Continuing Studies), and 69% of CMU&#39;s cohort already paid for an AI plan (<a href="./landscape-update-2026-10.html#non-major-studios-run-five-or-six-weeks-and-assume-students-pay">update report</a>). With an AI tutor harming first-generation students most in a large trial (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>), a free-tools course is an equity choice, provided it adds friction for everyone rather than more AI help.</td><td><a href="./../TOOLS.html">Tool Handout</a> · <a href="./../SYLLABUS.html#10-tools-and-cost">Syllabus §10</a></td></tr><tr><td><strong>A primary tool and two fallbacks per layer; switching is a planned drill</strong></td><td>In CMU 15-113, free credits on several tools ran out mid-assignment for at least one student (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). The report recommends teaching usage dashboards in week 1 and practicing the switch before it&#39;s urgent. In October 2026 the fallbacks, not the primaries, took the cuts (Gemini Free&#39;s default model, v0&#39;s credits, Replit&#39;s free plan, Antigravity&#39;s models), so the fallbacks are now the course&#39;s thinnest layer and get re-tested before each cohort (<a href="./landscape-update-2026-10.html#copilot-still-anchors-a-0-course-while-four-free-tiers-shrank">update report</a>).</td><td><a href="./../TOOLS.html">Tool Handout</a> · <a href="./../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a> · <a href="./../weeks/10-servers-and-deployment/">week 10</a> provider-swap drill</td></tr><tr><td><strong>Two-layer materials</strong>: a concept layer that names no versions or limits, plus one dated tool handout</td><td>Nearly every tool a 2025 syllabus would have used changed its free tier, price, name or owner within fifteen months, and several disappeared (<a href="./landscape-report-2026-09.html#free-tiers-still-exist-in-2026-but-they-are-capped-age-restricted-and-change-monthly">report</a>). Recorded screen demos go out of date within months (<a href="https://vibegym.space/blog/best-vibe-coding-courses-for-beginners" target="_blank" rel="noreferrer">VibeGym</a>); Maven revises its curriculum every quarter (<a href="https://maven.com/kentro/context-engineering-for-coding" target="_blank" rel="noreferrer">Maven</a>).</td><td><a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">CONTRIBUTING: two-layer rule</a> · <a href="./../TOOLS.html">Tool Handout</a></td></tr><tr><td><strong>Copilot in VS Code, in a Codespace, as the backbone</strong> from week 7</td><td>It is the most dependable no-cost agent path: agent mode, MCP and a CLI on the free plan, all three operating systems, and no 18+ restriction (<a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">GitHub Docs</a>); re-checked unchanged on 21 October 2026 (<a href="./landscape-update-2026-10.html#copilot-still-anchors-a-0-course-while-four-free-tiers-shrank">update report</a>). A remote environment such as Codespaces is a recommended sandbox for agents (<a href="https://simonwillison.net/2025/Sep/30/designing-agentic-loops/" target="_blank" rel="noreferrer">Willison</a>).</td><td><a href="./../setup/codespaces.html">GitHub Codespaces</a> · <a href="./../weeks/07-read-and-debug/">Week 7</a> · <a href="./../weeks/11-agents/">Week 11</a></td></tr><tr><td><strong>Switch LLM providers by configuration</strong>, not code</td><td>Major free providers accept OpenAI&#39;s request format, so an app that reads the base URL from an environment variable can switch by changing one setting (<a href="./landscape-report-2026-09.html#free-tiers-still-exist-in-2026-but-they-are-capped-age-restricted-and-change-monthly">report</a>).</td><td><a href="./../weeks/09-apis-and-secrets/">Week 9</a> · <a href="./../weeks/10-servers-and-deployment/">Week 10</a></td></tr><tr><td><strong>GitHub is the save point</strong> for everything, whatever tool made it</td><td>Builders disappear or expire: GitHub Spark and Firebase Studio were shut down, and Replit&#39;s free published apps expire, taking work with them (<a href="./landscape-report-2026-09.html#give-every-layer-a-primary-tool-and-two-fallbacks">report</a>). An agent&#39;s own checkpoints are &quot;not a replacement for git&quot; (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code best practices</a>). Strong version control is one of DORA&#39;s conditions for AI to help (<a href="https://services.google.com/fh/files/misc/2025_dora_ai_capabilities_model.pdf" target="_blank" rel="noreferrer">DORA</a>).</td><td><a href="./../setup/github-basics.html">GitHub basics</a> · <a href="./../resources/git-cheatsheet.html">git cheat sheet</a></td></tr><tr><td><strong>Variant stacks for under-18 and EEA/UK/Swiss cohorts</strong></td><td>Several tools are 18+ only, and the Gemini API&#39;s free tier may not serve users in the EEA, UK or Switzerland (<a href="./landscape-report-2026-09.html#free-tiers-still-exist-in-2026-but-they-are-capped-age-restricted-and-change-monthly">report</a>). Settle this before enrollment, not in week one.</td><td>Course variants (instructor materials)</td></tr></tbody></table><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>Oral walkthroughs in weeks 8, 12 and 14</strong>, clustered in the agent weeks</td><td>CMU 15-113 follows each project with a mock-job-interview check; UCSD can hold a grade until a student walks staff through the code; CS1-LLM required a video explaining one function (<a href="https://www.cs.cmu.edu/~113/" target="_blank" rel="noreferrer">CMU 15-113</a>; <a href="https://ucsd-cse-115-215.github.io/sp26/index.html" target="_blank" rel="noreferrer">UCSD</a>; <a href="https://arxiv.org/pdf/2406.15379" target="_blank" rel="noreferrer">CS1-LLM</a>). 68% of surveyed educators had already changed their assessment, oral defenses among the changes (<a href="https://acm-education-genai-task-force.github.io/ACM_Taskforce_GenAI_Report_16Feb26.pdf" target="_blank" rel="noreferrer">ACM Task Force</a>). Understanding fell when agents took over at CMU, so checks increase in the agent weeks rather than fading out. CS1-LLM&#39;s 10–15 minutes per project gives a staffing estimate. A 2026 CS1 course with weekly oral code reviews kept exam scores steady while AI pasting rose (<a href="https://arxiv.org/abs/2605.21374" target="_blank" rel="noreferrer">Fowles et al.</a>), and a 2026 review proposes four &quot;evidence obligations&quot; (explain, verify, modify, account) that map onto the walkthroughs&#39; four scoring areas (<a href="https://arxiv.org/abs/2609.29473" target="_blank" rel="noreferrer">Mahmoud</a>).</td><td><a href="./../assessment/oral-walkthroughs.html">Oral Walkthroughs</a></td></tr><tr><td><strong>Publish six skills students must show without AI</strong>, and require each to be shown once</td><td>31.1% of CS1-LLM students were not confident which problems they should be able to solve without the AI, and the instructors said they should have spelled it out (<a href="https://arxiv.org/pdf/2406.15379" target="_blank" rel="noreferrer">CS1-LLM</a>). The October review found the skills weren&#39;t really gated: exit tickets are completion-graded and walkthrough scores are compensatory (review A-09). Since October 2026 each skill must be shown at least once in a walkthrough, retake or follow-up, and all six are needed for a C or higher.</td><td><a href="./../resources/without-ai-skills.html">Six Skills You Must Show Without AI</a> · <a href="./../assessment/oral-walkthroughs.html#the-six-skills-you-must-show-without-ai">walkthroughs</a></td></tr><tr><td><strong>AI-free reflections and peer reviews</strong>, submitted on Canvas</td><td>CMU 17-316 bans AI from reflections, which must describe concrete moments when the tool surprised the student (<a href="https://ai-developer-tools.github.io/assignments/HW1/" target="_blank" rel="noreferrer">CMU 17-316 HW1</a>); UCSD bans AI from peer reviews (<a href="https://ucsd-cse-115-215.github.io/sp26/index.html" target="_blank" rel="noreferrer">UCSD</a>). Learners misjudge their own learning when AI helps (<a href="https://dl.acm.org/doi/10.1145/3632620.3671116" target="_blank" rel="noreferrer">Prather et al.</a>; <a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al.</a>); writing without it is where that shows. Since October 2026 this graded personal writing goes on Canvas, not in public repositories (University of Idaho FSH 4700 F-6 and FSH 2600; review A-02–A-04).</td><td><a href="./../templates/REFLECTION.html">REFLECTION template</a> · <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW template</a> · <a href="./../assessment/rubrics.html#reflections-and-peer-reviews">rubric</a></td></tr><tr><td><strong>Labs graded on effort, with cheap process logs</strong> (<code>PROMPTS.md</code>)</td><td>CMU 15-113 grades homework on effort; Utah grades in-class work on effort and fails assignments with missing AI logs; Michigan requires an AI log (<a href="https://www.cs.cmu.edu/~113/" target="_blank" rel="noreferrer">CMU 15-113</a>; <a href="https://github.com/utah-cs3960-sp26/syllabus/blob/main/syllabus.md" target="_blank" rel="noreferrer">Utah</a>; <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">UMich</a>). Pasting share links into a file keeps logs cheap (<a href="https://kelloggm.github.io/martinjkellogg.com/teaching/cs485-sp26/" target="_blank" rel="noreferrer">NJIT</a>). Effort grading plus oral checks avoids an arms race over detecting AI use.</td><td><a href="./../assessment/rubrics.html#weekly-labs-and-homework">rubric</a> · <a href="./../templates/PROMPTS.html">PROMPTS template</a></td></tr><tr><td><strong>Capstone graded on spec, tests, security and deployment</strong>; a working demo is required but not sufficient</td><td>AI makes brittle prototypes easy, so Utah gives credit only for edge cases, how features interact, and taste (<a href="https://github.com/utah-cs3960-sp26/syllabus/blob/main/syllabus.md" target="_blank" rel="noreferrer">Utah</a>); Michigan&#39;s rubric is half spec and design, half implementation and tests (<a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">UMich</a>).</td><td><a href="./../assessment/rubrics.html#capstone">capstone rubric</a> · <a href="./../projects/capstone.html">capstone brief</a></td></tr><tr><td><strong>Participation counts (15%)</strong>, across 30 studios</td><td>In the syllabus study, all conventionally graded courses counted participation, at a median weight of 17.5% (<a href="https://arxiv.org/abs/2608.05898" target="_blank" rel="noreferrer">Geng et al.</a>).</td><td><a href="./../assessment/rubrics.html#in-class-work-and-participation">rubric</a></td></tr></tbody></table><h3 id="teaching-format" tabindex="-1">Teaching format <a class="header-anchor" href="#teaching-format" aria-label="Permalink to &quot;Teaching format&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>Concept talks of 15 minutes or less; most studio time is lab</strong></td><td>Learner reviews reward building and punish lecture-heavy courses (<a href="https://www.coursera.org/learn/claude-code/reviews" target="_blank" rel="noreferrer">Coursera reviews</a>).</td><td>Every week&#39;s <code>slides.md</code>, e.g. <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-01.html" target="_blank" rel="noreferrer">week 1</a></td></tr><tr><td><strong>Core and stretch homework tiers</strong>, with a &quot;Minimum to keep up&quot; box</td><td>Maven splits homework this way (<a href="https://maven.com/kentro/context-engineering-for-coding" target="_blank" rel="noreferrer">Maven</a>). Weaker students benefit least from AI (<a href="https://acm-education-genai-task-force.github.io/ACM_Taskforce_GenAI_Report_16Feb26.pdf" target="_blank" rel="noreferrer">ACM Task Force</a>; <a href="https://dl.acm.org/doi/10.1145/3632620.3671116" target="_blank" rel="noreferrer">Prather et al.</a>), so the core tier stays achievable and support concentrates there. Stated times must add up: CMU re-estimated its API and backend homeworks from 2–3 hours to about six (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>), and the October review found several weeks over budget on paper (review A, F07, F14).</td><td>Every week&#39;s <code>homework.md</code>, e.g. <a href="./../weeks/01-hello-vibe-coding/homework.html">week 1</a></td></tr><tr><td><strong>One workflow, the Safe Loop, in every lab from week 3</strong>, plus the two-strikes rule, <em>check first</em> and <em>teach back</em></td><td>Vendor guides and practitioners describe nearly the same loop: plan, small task, verify with evidence, read the diff, commit (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code</a>; <a href="https://learn.chatgpt.com/guides/best-practices" target="_blank" rel="noreferrer">Codex</a>; <a href="https://addyosmani.com/blog/ai-coding-workflow/" target="_blank" rel="noreferrer">Osmani</a>; <a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Willison</a>). Observed professionals plan first and check all agent output (<a href="https://arxiv.org/pdf/2512.14012" target="_blank" rel="noreferrer">Huang et al.</a>). After two failed corrections, start fresh (<a href="https://code.claude.com/docs/en/best-practices" target="_blank" rel="noreferrer">Claude Code</a>). <em>Support for the loop itself is practitioner experience, not trials.</em> The two habits added in October have more direct support: independent tests catch more faults (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>), and an explanation gate cut AI-off maintenance failures from 77% to 39% (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>).</td><td><a href="./../resources/safe-loop.html">The Safe Loop</a> · <a href="./../resources/prompt-patterns.html">prompt patterns</a></td></tr><tr><td><strong>A hint-only course tutor</strong>, kept narrow: the only AI allowed in the Debug Clinic, and optional elsewhere</td><td>Unrestricted AI raised practice scores 48% but cut exam scores 17%; a hint-only tutor raised practice 127% with no significant exam harm (<a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al.</a>). CS50&#39;s Duck and CodeAid follow the same idea in programming (<a href="https://cs.harvard.edu/malan/publications/V1fp0567-liu.pdf" target="_blank" rel="noreferrer">Liu et al.</a>; <a href="https://dl.acm.org/doi/10.1145/3613904.3642773" target="_blank" rel="noreferrer">CodeAid</a>). In October 2026, a 2,379-student trial found that a course-integrated AI tutor <em>lowered</em> final grades by 0.37 standard deviations and platform participation by 0.90, most for first-generation students (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>), so the course does not add a course-wide tutor. <em>Bastani studied math, the new trial&#39;s tutor design is not described, and this tutor is untested in this course.</em></td><td><a href="./../resources/tutor-mode.html">Tutor mode</a> · <a href="./../weeks/07-read-and-debug/">Week 7</a></td></tr><tr><td><strong>The Game in an Hour</strong> in week 3</td><td>Adapted from CMU&#39;s one-hour game homework (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). Games give instant visual feedback and need no backend. In Fall 2026 CMU turned it into a 30-minute in-class sprint followed by up to four hours at home, and satisfaction and confidence rose (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>); this course keeps the hour whole inside one 75-minute studio (week 3&#39;s Studio B) and continues the game in the homework and in week 4. Graded on effort, and anyone may do it untimed.</td><td><a href="./../weeks/03-prompting-and-save-points/">Week 3</a></td></tr><tr><td><strong>Code handoff and human-vs-AI review</strong> in week 14, the review done on a real pull request</td><td>CMU 15-113&#39;s HW7 has students swap unfinished games and finish each other&#39;s (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>); Stanford grades a comparison of a student&#39;s own review with an AI reviewer&#39;s (<a href="https://github.com/mihail911/modern-software-dev-assignments/blob/ca2df55b78d6194612b65ae3fbfaa55a4678a683/week7/assignment.md" target="_blank" rel="noreferrer">W7 spec</a>). Pull requests were never taught although pairs had to merge through them, so week 12 now teaches them and the week 14 review is a pull-request review (review M4, H7/H9).</td><td><a href="./../weeks/12-pull-requests/">Week 12</a> · <a href="./../weeks/14-security-and-review/">Week 14</a> · <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW template</a> · <a href="./../resources/git-cheatsheet.html#branches-and-pull-requests">branches and pull requests</a></td></tr></tbody></table><h3 id="safety-privacy-and-openness" tabindex="-1">Safety, privacy and openness <a class="header-anchor" href="#safety-privacy-and-openness" aria-label="Permalink to &quot;Safety, privacy and openness&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Decision</th><th>Evidence</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>A nine-rule safety contract</strong>, skimmed before Studio 1 and signed on Canvas in week 1, each rule with a plain gloss and the week it&#39;s taught</td><td>Each rule answers a real incident: destructive agents (<a href="https://fortune.com/2025/07/23/ai-coding-tool-replit-wiped-database-called-it-a-catastrophic-failure/" target="_blank" rel="noreferrer">Replit</a>, <a href="https://incidentdatabase.ai/cite/1178/" target="_blank" rel="noreferrer">Gemini CLI</a>, <a href="https://www.tomshardware.com/tech-industry/artificial-intelligence/googles-agentic-ai-wipes-users-entire-hard-drive-without-permission-after-misinterpreting-instructions-to-clear-a-cache-i-am-deeply-deeply-sorry-this-is-a-critical-failure-on-my-part" target="_blank" rel="noreferrer">Antigravity</a>, <a href="https://ia.acs.org.au/article/2026/gone-in-9-seconds--ai-agent-deletes-company-database.html" target="_blank" rel="noreferrer">PocketOS</a>); poisoned rules files and skills (<a href="https://www.pillar.security/blog/new-vulnerability-in-github-copilot-and-cursor-how-hackers-can-weaponize-code-agents" target="_blank" rel="noreferrer">Pillar Security</a>; <a href="https://thehackernews.com/2026/07/new-hallusquatting-attack-could-trick.html" target="_blank" rel="noreferrer">HalluSquatting</a>); invented and hijacked packages (<a href="https://arxiv.org/abs/2605.17062" target="_blank" rel="noreferrer">arXiv 2605.17062</a>; <a href="https://socket.dev/blog/tensorlake-compromise" target="_blank" rel="noreferrer">Socket</a>); leaked secrets and stolen AI keys (<a href="https://blog.gitguardian.com/the-state-of-secrets-sprawl-2026/" target="_blank" rel="noreferrer">GitGuardian</a>; <a href="https://techcrunch.com/2026/10/19/hackers-hit-ai-coding-tool-opencode-running-up-charges-on-users-ai-accounts/" target="_blank" rel="noreferrer">TechCrunch</a>); agents that publish (<a href="https://thehackernews.com/2026/09/ai-coding-agents-exposed-13000-internal.html" target="_blank" rel="noreferrer">PixelLeak</a>); copyright (<a href="https://www.copyright.gov/ai/Copyright-and-Artificial-Intelligence-Part-2-Copyrightability-Report.pdf" target="_blank" rel="noreferrer">USCO</a>). Signing it in week 0, framed by disaster stories and full of untaught terms, put students off (review F09).</td><td><a href="./../setup/safety-contract.html">Safety Contract</a> · <a href="./../resources/case-studies.html">case studies</a></td></tr><tr><td><strong>Privacy settings on day one</strong></td><td>Several consumer AI plans train on chats and coding sessions by default unless users opt out (<a href="https://www.anthropic.com/news/updates-to-our-consumer-terms" target="_blank" rel="noreferrer">Anthropic</a>; <a href="https://github.blog/news-insights/company-news/updates-to-github-copilot-interaction-data-usage-policy/" target="_blank" rel="noreferrer">GitHub</a>), and some let human reviewers read samples (<a href="https://support.google.com/gemini/answer/13594961?hl=en" target="_blank" rel="noreferrer">Gemini privacy hub</a>).</td><td><a href="./../setup/privacy-settings.html">Privacy settings</a></td></tr><tr><td><strong>Three project rules</strong>: no real payments, no real personal data about others, nothing you&#39;d miss if an agent deleted it</td><td>Free hosting tiers prohibit commercial use (<a href="https://vercel.com/docs/plans/hobby" target="_blank" rel="noreferrer">Vercel Hobby</a>; <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/github-pages-limits" target="_blank" rel="noreferrer">GitHub Pages</a>); free tiers train on inputs; agents have deleted real data (<a href="https://fortune.com/2025/07/23/ai-coding-tool-replit-wiped-database-called-it-a-catastrophic-failure/" target="_blank" rel="noreferrer">Fortune</a>).</td><td><a href="./../SYLLABUS.html#6-projects">Syllabus §6</a></td></tr><tr><td><strong>The lethal trifecta and Rule of Two</strong> in the week 14 security checklist</td><td>Coding agents usually combine private data, untrusted content and a way to send data out (<a href="https://simonwillison.net/2025/Jun/16/the-lethal-trifecta/" target="_blank" rel="noreferrer">Willison</a>); an agent should hold no more than two without human approval (<a href="https://ai.meta.com/blog/practical-ai-agent-security/" target="_blank" rel="noreferrer">Meta</a>). Each 2026 prompt-injection case combined all three, and in each the vendor left the user as the last line of defense (<a href="https://adversa.ai/blog/cryptographic-context-injection-github-copilot/" target="_blank" rel="noreferrer">Adversa</a>; <a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-ai-coding-agent-ci-prompt-injection-202608/" target="_blank" rel="noreferrer">CSA</a>): hence safety contract rule 9.</td><td><a href="./../templates/SECURITY_CHECKLIST.html">SECURITY_CHECKLIST template</a></td></tr><tr><td><strong>An open license, a public website and a private source</strong></td><td>CMU 17-316&#39;s openly licensed course was adapted at Memphis and NJIT within a semester, and outside adopters help keep materials current (<a href="https://ai4sd-s26-memphis.github.io/" target="_blank" rel="noreferrer">Memphis</a>; <a href="https://kelloggm.github.io/martinjkellogg.com/teaching/cs485-sp26/" target="_blank" rel="noreferrer">NJIT</a>). Everything students use is public under that license: the website and the starter template repositories. Since November 2026 the source repository, which also holds the instructor notes, answer keys and exit tickets, is private, so students can&#39;t read the keys or the exit-ticket questions before class; the build publishes the website to a separate public repository.</td><td><a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> · <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/blob/main/LICENSE-CODE" target="_blank" rel="noreferrer">LICENSE-CODE</a> · <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">CONTRIBUTING</a></td></tr></tbody></table><hr><h2 id="november-2026-update" tabindex="-1">November 2026 update <a class="header-anchor" href="#november-2026-update" aria-label="Permalink to &quot;November 2026 update&quot;">​</a></h2><p>In November 2026 the instructor split the course in two and moved this one to a full semester. These are decisions by the instructor rather than findings of a new review, so the &quot;Why&quot; column gives the reasons and the evidence already in the course&#39;s research; it says where the evidence is thin. The week-folder files were rewritten to match, with each old week&#39;s Studio A content becoming the first new week of a pair and its Studio B content the second.</p><table tabindex="0"><thead><tr><th>Change</th><th>Why</th><th>Where</th></tr></thead><tbody><tr><td><strong>Two courses instead of one.</strong> This course, <em>Building Apps with AI</em> (CS [2xxx]), for students from any major after one programming course; a separate upper-division course, <em>Engineering Software with AI</em> (CS [4xxx]/[5xxx]), for CS seniors and graduate students after CS 3383 Software Engineering</td><td>Courses in this genre already serve two audiences. The syllabus study found 23 upper-division US courses that require generative AI in graded software work; Utah&#39;s expects experienced programmers and Northeastern&#39;s is at master&#39;s level, while CS1-LLM and CMU 15-113 are introductory (<a href="./landscape-report-2026-09.html#existing-courses-start-with-vibe-coding-then-hand-students-more-autonomous-tools">report</a>; <a href="https://arxiv.org/abs/2608.05898" target="_blank" rel="noreferrer">Geng et al.</a>). The instructor judged that one course couldn&#39;t serve both well: CS seniors are ready for agent and team practice at professional depth, while students from other majors need the web, git and the safety habits first. CS students past CS 3383 are pointed to the upper-division course</td><td><a href="./../SYLLABUS.html">Syllabus</a> · variants: experienced programmers</td></tr><tr><td><strong>New prerequisite: one programming course in any language</strong> (for example CS 1112, CS 1120 or CS 2120, or another department&#39;s course), or equivalent experience, or instructor permission</td><td>In the eight-week design the beginner material was the slowest part: labs ran long because &quot;first time ever&quot; skills sat in expert-sized slots (review A), and the first code students wrote got 20 minutes (review H11, M1). CMU 15-113 is open to students who have taken only the intro programming course, and 71% of its fall cohort had finished that course or beyond (<a href="./landscape-report-2026-09.html#existing-courses-start-with-vibe-coding-then-hand-students-more-autonomous-tools">report</a>; <a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>). A campus-wide course with one programming course behind it can raise the hand-coding bar a little (next row), and drop explanations of what a variable or a loop is, while still defining every web and tool term: most students have written Python but not HTML, CSS, JavaScript, git or a terminal command. <em>No study shows how much programming a student needs before vibe coding safely</em> (<a href="#what-nobody-knows-yet">open questions</a>); one course is a judgment</td><td><a href="./../SYLLABUS.html">Syllabus</a> · <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a></td></tr><tr><td><strong>A higher hand-coding bar</strong>: hand edits are small real code changes; &quot;You write it&quot; means writing a function from a short spec; students write their own validation tests (skeletons become hints); the first automated test moves to week 4, &quot;check first&quot; means an automated test from week 6 where the logic allows it, and Project 1 needs at least three automated tests of its pure logic</td><td>Coding practice, not awareness, predicted who checked AI-written code (<a href="https://arxiv.org/html/2605.24521v1" target="_blank" rel="noreferrer">Fawzy et al.</a>); debugging is the skill AI use erodes most (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic</a>); independently written tests catch more faults than tests written after the code (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). Experience is no reason to skip checking: experienced developers were 19% slower with AI while believing they were faster (<a href="https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/" target="_blank" rel="noreferrer">METR</a>). The AI-off work, the walkthroughs and the six skills stay as they were</td><td><a href="./../resources/safe-loop.html#check-first">Safe Loop</a> · <a href="./../weeks/04-undo-compare-explain/">Week 4</a> · <a href="./../weeks/08-own-it/">Week 8</a> · <a href="./../projects/project-1-useful-tool.html">Project 1</a></td></tr><tr><td><strong>A Week 0 bridge page, &quot;From Python to JavaScript&quot;</strong></td><td>The prerequisite can be met in any language, usually Python, and the course&#39;s code is JavaScript in web pages. A self-paced 60–90 minute page carries the language comparison, so labs can stay on the week&#39;s skill and add only one-line comparisons where JavaScript trips up Python programmers (<code>===</code>, <code>null</code> and <code>undefined</code>, <code>await</code>)</td><td><a href="./../setup/python-to-javascript.html">From Python to JavaScript</a></td></tr><tr><td><strong>16 weeks, still 3 credits, with two 75-minute studios a week</strong> (Studio A — Learn &amp; build, Studio B — Workshop) plus about 6 hours outside class: about 8.5 hours a week instead of 17. The eight-week accelerated design is kept as a variant</td><td>Two 75-minute meetings fit a normal University timetable (for example Tuesday and Thursday), where a 17-hour week and two 3-hour studios had to be fitted around students&#39; other courses. The workload stays at about 135 hours (catalog Regulation D-1). Spreading it out gives spaced practice: each skill comes back over more weeks before it is checked, and the delayed-recall exit-ticket question now reaches back two weeks, because recall of AI-assisted work fades within days (<a href="https://arxiv.org/abs/2609.21194" target="_blank" rel="noreferrer">Bergh et al.</a>). Stated times must still add up (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>). <em>No study compares an eight-week and a 16-week version of a course like this</em></td><td><a href="./../SYLLABUS.html">Syllabus</a> · instructor guide · 8-week variant</td></tr><tr><td><strong>Scheduled around the final-examination rules.</strong> No exit ticket, walkthrough or anything exam-like in week 15; walkthrough 3 moves to week 14; the Project Fair runs in the course&#39;s 2-hour final exam slot in week 16</td><td>University of Idaho Regulation H-1-a: &quot;No quizzes or exams may be given in lecture-recitation periods during the week before finals week&quot;; H-1-b sets the final examination period (<a href="https://catalog.uidaho.edu/general-requirements-academic-procedures/h-final-examinations/" target="_blank" rel="noreferrer">UIdaho catalog, Regulation H</a>). Week 15 becomes a polish week, and the fair, the course&#39;s final assessed event, takes the slot the University reserves for it</td><td><a href="./../weeks/14-security-and-review/">Week 14</a> · <a href="./../weeks/15-ship-it/">Week 15</a> · <a href="./../weeks/16-project-fair/">Week 16</a> · instructor guide</td></tr><tr><td><strong>Course title: <em>Building Apps with AI</em></strong>, not &quot;Vibe Coding&quot; or &quot;AI Programming&quot;</td><td>The course is being proposed as a new catalog course, and the University Curriculum Committee was uneasy with &quot;vibe coding&quot; as a title. A catalog title should outlast a 2025 buzzword whose meaning had already shifted (Karpathy moved to &quot;agentic engineering&quot; in 2026, <a href="./landscape-report-2026-09.html#the-field-moved-from-vibe-coding-to-agentic-engineering-in-fourteen-months">report</a>), and the course itself teaches students to move past careless vibe coding. &quot;AI Programming&quot; was ruled out too: on a transcript it reads as a course on building AI systems. <em>Building Apps with AI</em> names what students make, deployed web apps, in words that suit any major, and it sits clearly apart from the upper-division <em>Engineering Software with AI</em>: one course builds apps, the other engineers software. The interim title, <em>Building Software with AI</em>, was too close to the sibling&#39;s. The term stays where it helps: the catalog description and week 1</td><td><a href="./../SYLLABUS.html#course-information">Syllabus</a> · <a href="./../weeks/01-hello-vibe-coding/">Week 1</a></td></tr><tr><td><strong>Tool drift over four months</strong>: the mid-course tool re-check moves to before week 9; students open their capstone database at least weekly in weeks 13–16; the agent weeks span several monthly allowance resets</td><td>Free databases pause when unused, and free allowances reset monthly (<a href="./../TOOLS.html">Tool Handout</a>); four months is long enough for a free tier to change, as four did in one month of 2026 (<a href="./landscape-update-2026-10.html#copilot-still-anchors-a-0-course-while-four-free-tiers-shrank">update report</a>)</td><td>pre-cohort checklist · <a href="./../resources/troubleshooting.html#supabase">troubleshooting</a></td></tr></tbody></table><h2 id="october-2026-update" tabindex="-1">October 2026 update <a class="header-anchor" href="#october-2026-update" aria-label="Permalink to &quot;October 2026 update&quot;">​</a></h2><p>In October 2026 the course was revised from three inputs: decisions by the instructor (a 3-credit, eight-week course at the University of Idaho, for cohorts of five or more), a review of the course in four parts (pedagogy and workload, student experience, assessment and policy, technical accuracy), and the <a href="./landscape-update-2026-10.html">October research update</a>. The tables below map each change to its evidence; week numbers are given in the current 16-week numbering, and where November 2026 changed a decision, the row says so. &quot;Review&quot; means that course review. It isn&#39;t published, so each row says what the finding was; the codes in brackets (such as H1, F09 or S-01) are kept for the maintainers&#39; records. The research report and notes are linked directly.</p><h3 id="credits-and-the-weekly-format" tabindex="-1">Credits and the weekly format <a class="header-anchor" href="#credits-and-the-weekly-format" aria-label="Permalink to &quot;Credits and the weekly format&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Why</th><th>Where</th></tr></thead><tbody><tr><td><strong>3 credits, about 135 hours</strong>, then in eight accelerated weeks (16 weeks since November 2026)</td><td>The old design was about 50 hours of student work, roughly one credit under the University&#39;s credit-hour definition (catalog Regulation D-1; review A-08). The instructor chose 3 credits, so the workload was raised to match rather than the credits lowered. 1- and 2-credit versions are kept as variants</td><td><a href="./../SYLLABUS.html#course-information">Syllabus</a> · variants</td></tr><tr><td><strong>Two studios a week</strong>: Studio A (learn and build) and Studio B (workshop); 3 hours each plus about 11 hours outside class until November 2026, now 75 minutes each over 16 weeks</td><td>Labs were overloaded: stated 90–110 minutes, realistically 115–165 minutes for a first-time learner, with unbudgeted set-up and &quot;first time ever&quot; skills in expert-sized slots (review A). Skills the capstone needs were assumed but never taught: pull requests, charts, external APIs, the Supabase connection, a first automated test (review H8/H10, M4). Studio B gives them a slot</td><td><a href="./../SYLLABUS.html#two-studios-a-week">Syllabus §4</a> · every week&#39;s <code>lab.md</code></td></tr><tr><td><strong>&quot;This week at a glance&quot;</strong>, Core and If-time parts, and a &quot;Minimum to keep up&quot; box</td><td>On a phone, one week&#39;s overview was 12.6 screens long, opened with the instructor&#39;s timetable, and didn&#39;t say what was required (review F03, F14). Each week needs the previous week&#39;s work, so students need to know the one thing they must have working (review M7)</td><td>Every week&#39;s <code>README.md</code> and <code>homework.md</code></td></tr><tr><td><strong>A recap slot and a delayed-recall exit-ticket question</strong> about an earlier project (since November 2026, the project from two weeks earlier)</td><td>Two days after a task, AI users recalled 39% of what they&#39;d done against 52% for web-search users (<a href="https://arxiv.org/abs/2609.21194" target="_blank" rel="noreferrer">Bergh et al.</a>). The recap was promised but had no slot (review M7)</td><td><a href="./../SYLLABUS.html#two-studios-a-week">Syllabus §4</a> · exit tickets</td></tr><tr><td><strong>Doubled estimates for the APIs and security homework</strong>, with work moved to stretch</td><td>CMU re-estimated similar homeworks from 2–3 hours to about six (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>); the APIs week was already over budget on paper (review H4, F07)</td><td>Weeks <a href="./../weeks/09-apis-and-secrets/">9</a>–<a href="./../weeks/10-servers-and-deployment/">10</a> and <a href="./../weeks/13-data-and-access/">13</a>–<a href="./../weeks/14-security-and-review/">14</a></td></tr></tbody></table><h3 id="course-wide-conventions" tabindex="-1">Course-wide conventions <a class="header-anchor" href="#course-wide-conventions" aria-label="Permalink to &quot;Course-wide conventions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Change</th><th>Why</th><th>Where</th></tr></thead><tbody><tr><td><strong>Check first:</strong> write the &quot;done when&quot; check before asking for the code, in a separate prompt; from week 6 an automated test where the logic allows it</td><td>Tests an AI wrote after faulty code caught 14% of faults, against 25% for independently written tests (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). Evidence about tools, not learners</td><td><a href="./../resources/safe-loop.html#check-first">Safe Loop</a></td></tr><tr><td><strong>Teach back:</strong> 2–3 sentences in <code>PROMPTS.md</code> before committing AI-written code, graded in the capstone Process row</td><td>With the AI switched off, 77% of unrestricted AI users failed a maintenance task, against 39% of those whose tool required an explanation first (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>)</td><td><a href="./../resources/safe-loop.html#teach-back">Safe Loop</a> · <a href="./../assessment/rubrics.html#capstone">capstone rubric</a></td></tr><tr><td><strong>An <code>Assisted-by:</code> line</strong> on AI-assisted commits (taught in week 3, required from week 11)</td><td>48.8% of 281 open-source AI policies require disclosure (<a href="https://arxiv.org/abs/2609.07542" target="_blank" rel="noreferrer">Hora et al.</a>); LLVM, OpenStack, OpenTelemetry and Fedora use this line (<a href="https://allthingsopen.org/articles/open-source-ai-contributions-assisted-by-git-trailer-standard" target="_blank" rel="noreferrer">All Things Open</a>)</td><td><a href="./../resources/safe-loop.html#the-assisted-by-line">Safe Loop</a></td></tr><tr><td><strong>Three habits from the first weeks</strong> (the card is in week 2): ask me questions first; show a reference; say what works</td><td>Students&#39; own top practices in CMU&#39;s fall survey (<a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>); the same habits in a practitioner discussion (<a href="https://news.ycombinator.com/item?id=49934037" target="_blank" rel="noreferrer">HN</a>)</td><td><a href="./../resources/prompt-patterns.html#the-three-habits">Prompt patterns</a></td></tr><tr><td><strong>The Goldfish test</strong> for every spec and <code>AGENTS.md</code> (weeks 5 and 12)</td><td>Michigan&#39;s fresh-session test (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">EGM</a>); writing skill predicts vibe-coding proficiency (<a href="https://arxiv.org/abs/2603.14133" target="_blank" rel="noreferrer">Thorgeirsson et al.</a>)</td><td><a href="./../resources/prompt-patterns.html#18-the-goldfish-test">Pattern 18</a></td></tr><tr><td><strong>Personal AI-use rules</strong>, written in week 2 and revised in week 16</td><td>Students who wrote their own rules did better in both arms of a seven-week pilot (<a href="https://arxiv.org/abs/2609.16784" target="_blank" rel="noreferrer">Azimi</a>)</td><td>Weeks <a href="./../weeks/02-ship-your-page/">2</a> and <a href="./../weeks/16-project-fair/">16</a></td></tr><tr><td><strong>Agents: approvals on, never autopilot; <code>AGENTS.md</code> gets a Scope section, taught as advice, not enforcement</strong></td><td>Removing a scope statement raised one agent&#39;s out-of-scope actions from 0% to 17.1%, and ask-before-continuing harnesses overstepped least (<a href="https://arxiv.org/pdf/2605.18583" target="_blank" rel="noreferrer">Qu et al.</a>); an explicit scope line cut simulated attacks from 26/50 to 4/49, not to zero (<a href="https://www.aisi.gov.uk/blog/gpt-6-astra-performs-unsanctioned-supply-chain-attacks-in-simulations" target="_blank" rel="noreferrer">UK AISI</a>). Anthropic&#39;s docs call instruction files &quot;context, not enforced configuration&quot; (<a href="https://code.claude.com/docs/en/memory" target="_blank" rel="noreferrer">Claude Code docs</a>). Autopilot exfiltration was ruled the user&#39;s responsibility (<a href="https://adversa.ai/blog/cryptographic-context-injection-github-copilot/" target="_blank" rel="noreferrer">Adversa</a>). Real enforcement is the Codespace, approvals, scoped tokens, spending caps and RLS: the report&#39;s distinction between <em>rules</em> and <em>rails</em> (<a href="./landscape-update-2026-10.html#conclusion">conclusion</a>)</td><td><a href="./../templates/AGENTS.html">AGENTS.md template</a> · <a href="./../weeks/11-agents/">Week 11</a></td></tr><tr><td><strong>A ninth safety rule</strong> (&quot;agents don&#39;t publish, and untrusted content never shares a session with my secrets&quot;), and extensions to rules 4–8: spending caps, scoped tokens, backups out of reach; tests are not a security check; installing runs code, pin versions; skills, plugins, hooks and received folders; <code>Assisted-by:</code></td><td>Each addition answers a 2026 incident or study: <a href="./../resources/case-studies.html#13-pocketos-a-nine-second-database-deletion">PocketOS</a>, <a href="./../resources/case-studies.html#15-malware-that-hunts-for-ai-keys">stolen AI keys</a> and hard caps (<a href="https://simonwillison.net/2026/Oct/3/default-hard-budget-caps/" target="_blank" rel="noreferrer">Willison</a>); working-but-insecure code (<a href="https://semgrep.dev/blog/2026/claude-opus-5-5-susvibes-benchmark" target="_blank" rel="noreferrer">Semgrep</a>; <a href="https://arxiv.org/abs/2606.23130" target="_blank" rel="noreferrer">Deng et al.</a>); preinstall malware (<a href="https://socket.dev/blog/tensorlake-compromise" target="_blank" rel="noreferrer">Socket</a>); the received-folder attack (<a href="https://www.manifold.security/blog/ai-coding-agents-git-hijack" target="_blank" rel="noreferrer">Manifold</a>); <a href="./../resources/case-studies.html#14-pixelleak-agents-publish-13000-screenshots">PixelLeak</a> and autopilot exfiltration, which no old rule covered (<a href="./landscape-update-2026-10.html#priority-2-add-spending-caps-scope-and-a-ninth-rule-to-the-safety-contract">report P2</a>). Plain glosses and week tags respond to review F09</td><td><a href="./../setup/safety-contract.html">Safety contract</a></td></tr><tr><td><strong>Graded personal writing on Canvas, not in public repos</strong>; no classmates&#39; names in repos</td><td>Reflections, the signed contract and peer reviews were public by default (review A-02–A-04), against University policy on posting graded work (FSH 4700 F-6) and student records (FSH 2600, which applies FERPA)</td><td><a href="./../SYLLABUS.html#privacy-of-your-work">Syllabus §9</a></td></tr><tr><td><strong>&quot;Not every key is a secret&quot;</strong>: the Supabase publishable key in <code>public/config.js</code>; secret keys only in server environment variables; only publishable/secret keys taught</td><td>The APIs week said keys live in <code>.env</code> &quot;and nowhere else&quot; while the database week put the publishable key in the browser and the starter&#39;s <code>.env.example</code> put it on the server (review H8/H10, B-03). Supabase deprecates its legacy keys by the end of 2026 (<a href="https://supabase.com/docs/guides/api/api-keys" target="_blank" rel="noreferrer">Supabase</a>)</td><td><a href="./../resources/troubleshooting.html#which-key-goes-where">Troubleshooting</a> · capstone starter</td></tr><tr><td><strong>Supabase grants and RLS, always together</strong></td><td>From 30 October 2026, new tables need explicit grants (<a href="https://supabase.com/changelog/45329-breaking-change-tables-not-exposed-to-data-and-graphql-api-automatically" target="_blank" rel="noreferrer">Supabase changelog</a>); a bare grant to <code>anon</code> recreates the 16,326-database exposure (<a href="https://www.upguard.com/blog/everything-everywhere-systemic-data-exposure-in-supabase-apps" target="_blank" rel="noreferrer">UpGuard</a>). The trap is the report&#39;s inference from the two sources</td><td><a href="./../resources/troubleshooting.html#permission-denied-for-a-new-table">Troubleshooting</a> · <a href="./../weeks/13-data-and-access/">Week 13</a></td></tr><tr><td><strong>Vercel: submit the production URL and a screenshot</strong>; private organization repos can&#39;t deploy on the free plan</td><td>Vercel&#39;s free plan now deletes older deployments (<a href="https://vercel.com/changelog/hobby-projects-now-retain-fewer-deployments-to-free-up-storage" target="_blank" rel="noreferrer">Vercel changelog</a>); the organization block applies to private repos only (<a href="https://community.vercel.com/t/unable-to-deploy-from-organizational-private-repository/16334" target="_blank" rel="noreferrer">Vercel Community</a>)</td><td><a href="./../resources/troubleshooting.html#deploying-to-vercel">Troubleshooting</a></td></tr><tr><td><strong>AI-use labels always in words</strong>, square-bracket placeholders, one due-date wording, one walkthrough timing rule</td><td>The traffic lights differed only by color in 113 places (review F04); angle-bracket placeholders vanish when GitHub renders Markdown (review D, Low); due dates were worded three ways and walkthrough 3&#39;s timing differed across six files (review F03, M8, L3)</td><td>Everywhere</td></tr><tr><td><strong>Six skills gated</strong>; the integrity process follows the University&#39;s Student Code of Conduct</td><td>The skills weren&#39;t really required (review A-09). FSH 2300 names reliance on prohibited AI tools as academic dishonesty and requires the instructor to notify the student and the Dean of Students before any grade outcome (review A-01)</td><td><a href="./../resources/without-ai-skills.html#how-the-requirement-works">Without-AI skills</a> · <a href="./../SYLLABUS.html#academic-integrity">Syllabus §11</a></td></tr><tr><td><strong>A screen reader and keyboard guide</strong>, text versions of every diagram, and a published self-paced path with a &quot;Working alone?&quot; line for each pair activity</td><td>ASCII diagrams read as garble and overflowed on phones; the only screen-reader advice was in a hidden instructor note (review F05, F06, F11, F20). Self-paced learners were pointed to an unpublished guide whose links the site hides (review F10, F21)</td><td><a href="./../resources/accessibility.html">Accessibility guide</a> · <a href="./../resources/self-paced.html">Self-paced path</a></td></tr><tr><td><strong>A history-aware secret scan</strong> and committed lockfiles</td><td>The old scanner missed the course&#39;s own key formats and never read git history, yet its clean output counted as evidence; <code>npm audit</code> failed in every starter without a lockfile (review S-01, B-01, B-02)</td><td><a href="./../resources/troubleshooting.html#i-committed-a-secret">Troubleshooting</a> · starters</td></tr><tr><td><strong>Node.js 22 LTS (minimum 20.12)</strong></td><td>The starters need 20.12, and Node 20 has reached end of life (technical review)</td><td><a href="./../resources/troubleshooting.html#npm-command-not-found-or-the-wrong-node-version">Troubleshooting</a></td></tr></tbody></table><h3 id="week-by-week" tabindex="-1">Week by week <a class="header-anchor" href="#week-by-week" aria-label="Permalink to &quot;Week by week&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Week</th><th>Change</th><th>Why</th></tr></thead><tbody><tr><td>0</td><td>Split into &quot;Before Studio 1&quot; (about 60–90 minutes) and &quot;During week 1&quot;; contract and self-assessment on Canvas in week 1; privacy advice and the week 1 lab agree about chat history (November 2026 added the <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a> bridge)</td><td>Week 0 asked for 2–3.5 hours and a signature on untaught terms; two pages contradicted each other (review F09, F15, F16)</td></tr><tr><td>1–2</td><td>The three habits; personal AI-use rules; an accessibility check of your page; free AI-fluency pre-work (<a href="https://academy.claude.com/courses/ai-fluency-framework-foundations" target="_blank" rel="noreferrer">Anthropic Academy</a>)</td><td>Tool-agnostic judgment before tools (<a href="./notes/2026-10/online-courses-and-learner-feedback.html">October notes</a>); habits as above</td></tr><tr><td>3–4</td><td>Prompt makeover workshop; the <code>Assisted-by:</code> line; Willison&#39;s reading</td><td>Disclosure norms as above</td></tr><tr><td>5–6</td><td>The builder bake-off as a jigsaw; preview in a Codespace before committing, in Safe Loop order; the Goldfish test; a written peer spec review on Canvas</td><td>The bake-off overran the lab, and the old build loop committed before testing (review H1, H2)</td></tr><tr><td>7–8 (and 4)</td><td><code>git revert</code> practice before walkthrough 1; &quot;You write it&quot; with feature cards (30 minutes; since November 2026, a function written from a short spec); a first automated test from a worked example (since November 2026, in week 4)</td><td>Walkthrough 1 asked for a command not yet practiced; the first code students wrote got 20 minutes (review H11, M1); check first needs tests before the project weeks</td></tr><tr><td>9–10</td><td>Part 1 folded into the demo; provider swap and the history-aware secret check (now week 10); a fill-in test skeleton (since November 2026, a hint for tests students write themselves); an external-API mini-lesson; production URL</td><td>Overloaded lab and homework; tests with no worked example (review H3, H4, F07, H10)</td></tr><tr><td>11–12</td><td>Capstone repo created before class; SPEC for one criterion; 50+ minutes for the first agent run with check first and teach back; branches and pull requests; a planted bug in agent-written code; feature clinic; the <code>AGENTS.md</code> trial</td><td>The agents week crammed a new repo and a full spec into 20 minutes (review H5/H6); pull requests were never taught (review M4); planted bugs led to direct editing and better next attempts (<a href="https://arxiv.org/pdf/2607.05068" target="_blank" rel="noreferrer">Pădurean et al.</a>); configure-then-test, as in <a href="https://github.com/mihail911/modern-software-dev-assignments/blob/a6dcbf2090/week4/assignment.md" target="_blank" rel="noreferrer">CS146S</a></td></tr><tr><td>13–14</td><td>New case studies, with cases 12–14 as the default jigsaw; the hosted attack page; a Supabase connection worked example; a 20–30 minute AI-off maintenance task; the peer review as a pull-request review; a 7-minute injection demo; the handoff test as homework; student-facing Supabase and Vercel troubleshooting</td><td>The old cases were mostly from 2025 (<a href="./landscape-update-2026-10.html#priority-4-replace-the-old-breaches-with-this-years-case-studies">report P4</a>); the lab needed an extra repo and gave the database connection one sentence (review H7, H9, F08, F12, M6); AI-off maintenance is where the 77% vs 39% gap showed (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>)</td></tr><tr><td>15–16</td><td>A known-issues section in the README; walkthrough 3 in Studio A or by appointment (since November 2026, in week 14, because of Regulation H-1-a); revised AI-use rules; production URL, screenshot and a <code>v1.0</code> release</td><td>Michigan grades &quot;on evidence, not feature count&quot;, and saying what doesn&#39;t work is worth more than hoping nobody tries it (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/lectures/L08/slides.md" target="_blank" rel="noreferrer">L08 slides</a>)</td></tr><tr><td>All</td><td>Milestones defined once in the capstone brief; rescue starters for students who fall behind</td><td>Milestones disagreed across pages; each week needs the last week&#39;s artifact (review M7, M8)</td></tr></tbody></table><h3 id="what-the-october-evidence-did-not-change" tabindex="-1">What the October evidence did not change <a class="header-anchor" href="#what-the-october-evidence-did-not-change" aria-label="Permalink to &quot;What the October evidence did not change&quot;">​</a></h3><ul><li><strong>The overall shape.</strong> Nothing published between 25 September and 21 October 2026 overturns the Safe Loop, the ladder of tools, the AI-free walkthroughs or the $0 stack (<a href="./landscape-update-2026-10.html">update report</a>).</li><li><strong>No course-wide AI tutor.</strong> The new trial points the other way, so tutor mode stays narrow (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>).</li><li><strong>The same two evidence gaps</strong> remain: no semester-long trial of teaching non-programmers through vibe coding, and no study of spec-first or test-first teaching on real learners (<a href="./landscape-update-2026-10.html#professional-developers-trust-ai-only-where-they-can-verify-it">update report</a>).</li></ul><hr><h2 id="what-we-deliberately-did-not-do" tabindex="-1">What we deliberately did not do <a class="header-anchor" href="#what-we-deliberately-did-not-do" aria-label="Permalink to &quot;What we deliberately did not do&quot;">​</a></h2><p><strong>A course built around one vendor.</strong> Stanford&#39;s Fall 2025 course featured one partner tool per week. Its week 2 relied on a free year of Cursor Pro that has since closed to new sign-ups, so that week can no longer be reproduced as written (<a href="./landscape-report-2026-09.html#existing-courses-start-with-vibe-coding-then-hand-students-more-autonomous-tools">report</a>). Vendor academies are free but tied to one tool, and some need a paid plan (<a href="https://anthropic.skilljar.com/claude-code-101" target="_blank" rel="noreferrer">Anthropic Academy</a>). This course names products only where a step needs them and keeps the specifics in <a href="./../TOOLS.html">Tool Handout</a>.</p><p><strong>AI detectors.</strong> The course <em>requires</em> AI, so the question is never &quot;did you use it?&quot; but &quot;can you explain what you shipped?&quot; Educators are moving away from trying to make assignments AI-proof (<a href="https://acm-education-genai-task-force.github.io/ACM_Taskforce_GenAI_Report_16Feb26.pdf" target="_blank" rel="noreferrer">ACM Task Force</a>). Effort-graded labs, <code>PROMPTS.md</code> logs, AI-free writing and oral walkthroughs make detection unnecessary.</p><p><strong>Required paid tools.</strong> The report found that if a course <em>must</em> require one paid tier, the evidence supports a cheap editor-assistant upgrade or one month of a frontier agent timed to the agent weeks (now weeks 11–16). We made both optional (<a href="./../SYLLABUS.html#10-tools-and-cost">Syllabus §10</a>), because the free path works, and learners criticize courses that require paid subscriptions (<a href="https://www.coursera.org/learn/claude-code/reviews" target="_blank" rel="noreferrer">Coursera reviews</a>).</p><p><strong>Agents in week 1.</strong> Agents amplify whatever habits a student already has (<a href="https://cloud.google.com/blog/products/ai-machine-learning/announcing-the-2025-dora-report" target="_blank" rel="noreferrer">DORA</a>), and understanding dropped when agents took over at CMU (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>). The destructive-agent incidents in the <a href="./../resources/case-studies.html">case studies</a> show what an agent does without git, tests and containment. We borrowed the useful part of early agent teaching, showing how an agent works from the inside, but placed it in week 11 as <a href="https://github.com/Boyu-Zhang-UOI/vc101-be-the-agent" target="_blank" rel="noreferrer">Be the Agent</a>, with no AI at all.</p><p><strong>Cursor or Gemini CLI as the primary tools.</strong> Both were strong choices in 2025. By mid-2026, Cursor&#39;s free plan lacked MCP and its free student year had closed, and Gemini CLI&#39;s free Google login had ended, while its own README still advertised the old quota for months (<a href="./landscape-report-2026-09.html#free-tiers-still-exist-in-2026-but-they-are-capped-age-restricted-and-change-monthly">report</a>; dates in <a href="./../TOOLS.html">Tool Handout</a>). Copilot Free kept agent mode, MCP and a CLI at no cost, with no age restriction. Since October 2026, Cursor&#39;s free plan has been folded into a social-network subscription bundle (<a href="./../TOOLS.html">dates in TOOLS.md</a>).</p><p><strong>Banning outside AI in favor of a course tutor only.</strong> CS50 allows only its own tutor (<a href="https://cs50.harvard.edu/x/2026/honesty/" target="_blank" rel="noreferrer">CS50</a>). That suits a course whose goal is learning to program by hand. This course&#39;s goal is learning to direct AI tools safely, so AI is required, and the hint-only tutor is used only where the goal is the student&#39;s own thinking: the Debug Clinic.</p><p><strong>A course-wide AI tutor.</strong> It would be easy to add one to every lab. In a 2026 trial with 2,379 students, a course-integrated tutor lowered final grades and participation, most for first-generation students (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>). The course adds friction for everyone (check first, teach-backs, AI-off tasks, delayed recall) rather than more AI help for those who struggle.</p><p><strong>Grading on whether the app runs.</strong> A working demo is required for the capstone but earns little on its own. Robustness, specs, tests, security and explanation carry the grade, following <a href="https://github.com/utah-cs3960-sp26/syllabus/blob/main/syllabus.md" target="_blank" rel="noreferrer">Utah</a> and <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">Michigan</a>.</p><hr><h2 id="open-questions-and-how-this-course-measures-itself" tabindex="-1">Open questions and how this course measures itself <a class="header-anchor" href="#open-questions-and-how-this-course-measures-itself" aria-label="Permalink to &quot;Open questions and how this course measures itself&quot;">​</a></h2><h3 id="what-nobody-knows-yet" tabindex="-1">What nobody knows yet <a class="header-anchor" href="#what-nobody-knows-yet" aria-label="Permalink to &quot;What nobody knows yet&quot;">​</a></h3><p>The report is explicit about the gaps (<a href="./landscape-report-2026-09.html#ai-raises-output-but-lowers-understanding-unless-teachers-add-structure">report</a>; <a href="./landscape-report-2026-09.html#conclusion">conclusion</a>):</p><ul><li><strong>No controlled study has compared course orderings.</strong> The shared shape of existing courses rests on design rationale and student surveys (<a href="https://arxiv.org/abs/2608.05898" target="_blank" rel="noreferrer">Geng et al.</a>).</li><li><strong>No semester-long randomized trial has tested teaching non-programmers through vibe coding.</strong> Studies of novices vibe coding are small (19 students in <a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>) or surveys. The longest retention measures in the 2026 studies are 48 hours and one week (<a href="https://arxiv.org/abs/2609.21194" target="_blank" rel="noreferrer">Bergh et al.</a>; <a href="https://icer2026.acm.org/track/icer-2026-papers" target="_blank" rel="noreferrer">ICER 2026</a>).</li><li><strong>No study has tested whether writing specs or tests first helps novices learn.</strong> The case is practitioner consensus, plus one 2026 study about AI-written tests, not learners (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>).</li><li><strong>No study shows how much programming knowledge novices need to vibe-code safely.</strong> The <a href="./../resources/without-ai-skills.html">six skills</a> are an expert-consensus floor, not a measured one, and the November 2026 prerequisite of one programming course is a judgment, not a measured threshold.</li><li><strong>The best evidence for hint-only tutors is from high-school math</strong> (<a href="https://www.pnas.org/doi/10.1073/pnas.2422633122" target="_blank" rel="noreferrer">Bastani et al.</a>), and the largest 2026 trial found a course-integrated tutor harmful without describing its design (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>). The course tutor is an untested adaptation.</li><li><strong>Productivity evidence is contested.</strong> METR&#39;s 2025 and 2026 studies point in different directions, METR calls its 2026 estimates unreliable (<a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">METR 2026</a>), and it has published nothing since May 2026. Professionals&#39; trust is conditional: in Stack Overflow&#39;s 2026 survey only 6.6% trusted AI for important decisions (<a href="https://stackoverflow.co/company/press/archive/stack-overflow-annual-developer-survey-ai-trust-conditional" target="_blank" rel="noreferrer">Stack Overflow</a>).</li><li><strong>How much novices retain</strong> is the biggest unknown. The course&#39;s own delayed-recall questions and week 14 AI-off task can start producing that evidence (<a href="./landscape-update-2026-10.html#conclusion">update report</a>).</li></ul><h3 id="how-the-course-checks-itself" tabindex="-1">How the course checks itself <a class="header-anchor" href="#how-the-course-checks-itself" aria-label="Permalink to &quot;How the course checks itself&quot;">​</a></h3><p>Because of those gaps, the course measures its own students&#39; understanding before and after, as the report recommends.</p><table tabindex="0"><thead><tr><th>Measure</th><th>What it tells you</th><th>Where</th></tr></thead><tbody><tr><td><strong>Pre/post self-assessment</strong> against the eight learning outcomes</td><td>How students&#39; confidence changes over the course</td><td><a href="./../assessment/self-assessment.html">Self-Assessment: Before and After</a></td></tr><tr><td><strong>Exit tickets</strong>, weekly in weeks 1–14 and AI-free, with one delayed-recall question about the project from two weeks earlier</td><td>Which of the six skills are shaky, week by week, and what students still remember two weeks later</td><td>Exit tickets (instructor materials)</td></tr><tr><td><strong>The week 14 AI-off maintenance task</strong> on each student&#39;s own capstone</td><td>Whether students can change their own AI-built code without the AI: the measure on which the 2026 studies found the biggest gaps</td><td><a href="./../weeks/14-security-and-review/">Week 14</a></td></tr><tr><td><strong>Oral walkthrough results</strong> in weeks 8, 12 and 14</td><td>Whether understanding holds up once agents arrive: the CMU warning sign</td><td><a href="./../assessment/oral-walkthroughs.html">Oral Walkthroughs</a></td></tr><tr><td><strong>Confidence vs explanation</strong> in each reflection: rate your confidence, then explain the part you&#39;re least sure of</td><td>Calibration: does felt understanding match demonstrated understanding?</td><td><a href="./../templates/REFLECTION.html">REFLECTION template</a></td></tr><tr><td><strong>A two-question survey after each studio, a mid-course survey, and a short survey after each project</strong>, as CMU 15-113 runs (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">Student Wisdom report</a>; <a href="https://www.cs.cmu.edu/~113/bestPracticesF26.html" target="_blank" rel="noreferrer">CMU F26 report</a>)</td><td>Tool problems, workload, perceived understanding and code reading, early enough to act. With small cohorts, report nothing below five answers</td><td>Instructor guide (instructor materials)</td></tr><tr><td><strong>A log of tool failures and fallback switches</strong></td><td>Whether the fallbacks in TOOLS.md actually work for a cohort</td><td>Pre-cohort checklist (instructor materials)</td></tr></tbody></table><p>If you teach the course, compare self-assessment with walkthrough results. A gap between the two, especially in the agent weeks (11–16), is the signal the research predicts. Please share what you find through an issue or discussion (<a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">CONTRIBUTING</a>).</p><hr><h2 id="how-to-update-the-course" tabindex="-1">How to update the course <a class="header-anchor" href="#how-to-update-the-course" aria-label="Permalink to &quot;How to update the course&quot;">​</a></h2><ol><li><strong>Tool changes go in <a href="./../TOOLS.html">Tool Handout</a> only.</strong> That is the point of the <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">two-layer rule</a>. If a concept page needs changing because a tool changed, the page probably named something it shouldn&#39;t have.</li><li><strong>Before each cohort, and again at mid-course (before week 9), actually use every primary and fallback tool</strong> instead of trusting the docs; Google&#39;s own pages lagged its changes by months. The steps are in the pre-cohort checklist (instructor materials), and TOOLS.md keeps a calendar of announced changes (in late 2026: Supabase grants on 30 October, Antigravity&#39;s models on 2 November, Supabase&#39;s legacy keys at the end of the year; <a href="./landscape-update-2026-10.html#priority-5-put-nine-dated-changes-on-the-instructor-calendar">report P5</a>).</li><li><strong>Check age and region rules</strong> for the cohort and pick a stack from the course variants (instructor materials) before enrollment.</li><li><strong>New evidence</strong> goes into the <a href="./">research notes</a> with a link, then into this page if it changes a decision. Keep every claim linked to a source.</li><li><strong>New incidents</strong> can be added to the <a href="./../resources/case-studies.html">case studies</a> only with sources, and conflicting reports should be flagged.</li><li><strong>Report problems</strong> through the process in <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">Contributing and Style Guide</a>, and run its checks before sending a pull request.</li></ol><hr><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li>The full review: <a href="./landscape-report-2026-09.html">Teach the Loop, Not the Tool</a> (September 2026)</li><li>The October update: <a href="./landscape-update-2026-10.html">Free Tiers Shrink While Evidence Demands Friction</a> (25 September – 21 October 2026)</li><li>Research notes, with more detail and evidence labels: <ul><li><a href="./notes/university-courses.html">University courses</a></li><li><a href="./notes/online-industry-courses.html">Online and industry courses</a></li><li><a href="./notes/pedagogy-practices-risks.html">Pedagogy, practices and risks</a></li><li><a href="./notes/tools-chat-and-app-builders.html">Chat assistants and app builders</a></li><li><a href="./notes/tools-ide-cli-apis-hosting.html">IDEs, CLIs, APIs and hosting</a></li></ul></li><li>October 2026 notes: <ul><li><a href="./notes/2026-10/evidence-incidents-practices.html">Evidence, incidents and practices</a></li><li><a href="./notes/2026-10/university-courses-fall-2026.html">University courses, fall 2026</a></li><li><a href="./notes/2026-10/online-courses-and-learner-feedback.html">Online courses and learner feedback</a></li><li><a href="./notes/2026-10/tool-changes-since-september.html">Tool changes since September</a></li></ul></li></ul>',64)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
